target.css:
:root {
  --ink: #173b3a;
  --surface: #fffdf5;
  --panel: #e7f3e9;
  --deep: #164f4b;
  --mint: #54c7a5;
  --lime: #d7ee68;
  --sun: #f6bf4b;
  --coral: #ef7663;
  --line: #b8d3c7;
  --muted: #64817b;
  --white: #ffffff;
}

.grid-console {
  box-sizing: border-box;
  width: 500px;
  height: 282px;
  padding: 14px;
  overflow: hidden;
  color: var(--ink);
  background: var(--surface);
  border: 2px solid var(--deep);
  border-radius: 18px;
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 43px;
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.console-header h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.6px;
}

.status-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  color: var(--deep);
  background: var(--lime);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.4px;
}

.status-dot {
  width: 7px;
  height: 7px;
  background: var(--deep);
  border-radius: 50%;
}

.content-grid {
  display: grid;
  grid-template-columns: 1.28fr 0.92fr;
  gap: 10px;
  height: 170px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.battery-panel {
  box-sizing: border-box;
  padding: 11px 12px;
  background: var(--panel);
  border-radius: 12px;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-heading h2,
.dispatch-panel h2 {
  margin: 0;
  font-size: 12px;
  line-height: 1;
  font-weight: 800;
}

.panel-heading span {
  padding: 3px 5px;
  color: var(--deep);
  background: var(--mint);
  border-radius: 4px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.7px;
}

.percent-row {
  display: flex;
  align-items: end;
  gap: 7px;
  margin: 6px 0;
}

.percent-row strong {
  color: var(--deep);
  font-size: 27px;
  line-height: 0.9;
  letter-spacing: -1px;
}

.percent-row span {
  padding-bottom: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.charge-bar {
  height: 7px;
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
}

.charge-bar span {
  display: block;
  width: 78%;
  height: 100%;
  background: var(--deep);
  border-radius: 999px;
}

.source-list,
.dispatch-list {
  padding: 0;
  margin: 8px 0 0;
  list-style: none;
}

.source-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.source-item {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.source-icon {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: 6px;
  font-size: 11px;
}

.source-copy {
  display: grid;
  min-width: 0;
}

.source-copy b,
.dispatch-copy b {
  overflow: hidden;
  font-size: 10px;
  line-height: 1.1;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.source-copy small,
.dispatch-copy span {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.15;
}

.source-value {
  margin-left: auto;
  color: var(--deep);
  font-size: 9px;
  white-space: nowrap;
}

.dispatch-panel {
  box-sizing: border-box;
  padding: 11px 12px;
  background: var(--deep);
  border-radius: 12px;
  color: var(--white);
}

.dispatch-note {
  margin: 4px 0 0;
  color: var(--mint);
  font-size: 10px;
  font-weight: 700;
}

.dispatch-list {
  display: grid;
  gap: 7px;
}

.dispatch-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 7px;
  border-top: 1px solid var(--mint);
}

.dispatch-time {
  color: var(--sun);
  font-size: 11px;
  font-weight: 900;
}

.dispatch-copy {
  display: grid;
  min-width: 0;
}

.dispatch-copy b {
  color: var(--white);
}

.dispatch-copy span {
  color: var(--mint);
}

.console-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 31px;
}

.footer-date {
  color: var(--muted);
  font-size: 10px;
}

.footer-date b {
  color: var(--ink);
  font-weight: 800;
}

.arm-button {
  padding: 6px 10px;
  color: var(--white);
  background: var(--coral);
  border: 0;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 800;
}

